return [
    // 1-13: Cơm & bánh
    ['Bánh bèo chén tôm cháy', 1, 'bột gạo, bột năng, tôm tươi, hành lá, dầu ăn, nước mắm, đường, ớt, hành phi, tóp mỡ', 'Pha bột gạo và bột năng với nước, khuấy mịn rồi để bột nghỉ. Rót bột vào chén nhỏ và hấp đến khi mặt bánh trong, se lại. Rang tôm đã bóc vỏ với chút muối đến khô tơi, giã hoặc xay thành tôm cháy. Rưới mỡ hành, rắc tôm cháy, hành phi và tóp mỡ; dùng với nước mắm pha chua ngọt.'],
    ['Bánh bột lọc lá chuối', 1, 'bột năng, tôm đất, thịt ba chỉ, lá chuối, hành tím, nước mắm, đường, tiêu, dầu ăn', 'Ướp tôm và thịt ba chỉ với nước mắm, đường, tiêu; rim cùng hành tím đến săn và ráo. Nhồi bột năng với nước nóng đến khi dẻo, chia bột, bọc nhân tôm thịt rồi gói bằng lá chuối đã hơ mềm. Hấp bánh đến khi vỏ trong và nhân chín; dùng với nước mắm ớt.'],
    ['Bánh nậm tôm thịt', 1, 'bột gạo, bột năng, tôm, thịt heo xay, hành tím, hành lá, lá chuối, dầu ăn, nước mắm, tiêu', 'Xào tôm băm và thịt heo với hành tím, nêm nước mắm và tiêu, sau đó đảo đến khi nhân tơi. Khuấy bột gạo, bột năng với nước đến mịn rồi nấu lửa nhỏ đến khi sánh. Trải bột mỏng lên lá chuối, thêm nhân, gấp kín và hấp chín. Ăn nóng cùng nước mắm pha.'],
    ['Bánh ít trần nhân đậu xanh', 1, 'bột nếp, đậu xanh cà vỏ, hành lá, hành phi, dầu ăn, muối, tiêu, nước mắm', 'Ngâm đậu xanh rồi hấp mềm, nghiền nhuyễn và xào với hành phi, muối, tiêu thành nhân. Nhồi bột nếp với nước ấm và chút muối thành khối mềm, bọc nhân thành viên tròn dẹt. Luộc đến khi bánh nổi và vỏ trong, vớt ra áo nhẹ dầu hành. Dùng với nước mắm pha và hành phi.'],
    ['Bánh đúc nóng thịt băm', 1, 'bột gạo, bột năng, thịt heo xay, mộc nhĩ, hành tím, nước mắm, nước dùng, dầu ăn, hành phi, rau mùi', 'Ngâm mềm mộc nhĩ rồi băm nhỏ, xào với thịt heo và hành tím, nêm nước mắm, tiêu. Hòa bột gạo và bột năng với nước dùng, khuấy trên lửa nhỏ liên tục đến khi bột trong và dẻo. Múc bánh đúc nóng ra bát, rải thịt băm, chan nước mắm pha loãng và thêm hành phi, rau mùi.'],
    ['Bánh hỏi lòng heo', 1, 'bánh hỏi, lòng heo, gan heo, tim heo, thịt ba chỉ, giá đỗ, rau thơm, hành lá, dầu ăn, nước mắm', 'Rửa lòng, gan và tim với muối, chanh; luộc chín từng loại rồi thái miếng vừa ăn. Hấp bánh hỏi cho mềm, rưới dầu hành và rắc hành lá. Xếp bánh hỏi cùng lòng heo, thịt ba chỉ, giá và rau thơm. Dùng kèm nước mắm tỏi ớt và đồ chua.'],
    ['Bánh tằm bì nước cốt dừa', 1, 'bánh tằm, thịt heo, da heo, thính gạo, nước cốt dừa, bột năng, hành lá, dưa leo, rau thơm, nước mắm', 'Luộc thịt heo và da heo chín, thái sợi; trộn bì với thính, chút muối và tiêu. Nấu nước cốt dừa với ít muối, làm sánh nhẹ bằng bột năng hòa nước. Trụng bánh tằm, xếp cùng bì, dưa leo và rau thơm rồi chan nước cốt dừa. Dùng kèm nước mắm chua ngọt.'],
    ['Bánh căn trứng cút', 1, 'bột gạo, trứng cút, hành lá, tôm khô, dầu ăn, nước mắm, đường, dưa leo, xoài xanh', 'Pha bột gạo với nước đến độ sánh vừa, để nghỉ rồi khuấy lại. Làm nóng khuôn bánh căn, thoa dầu, rót bột và đập trứng cút lên từng khuôn; đậy nắp nướng đến khi bánh vàng đáy và trứng chín. Rắc hành lá và tôm khô rang. Ăn với nước mắm pha, dưa leo và xoài xanh.'],
    ['Bánh khọt tôm', 1, 'bột gạo, nước cốt dừa, tôm tươi, hành lá, bột nghệ, dầu ăn, rau sống, đồ chua, nước mắm', 'Khuấy bột gạo với nước cốt dừa, bột nghệ và nước đến mịn, để bột nghỉ. Ướp tôm với chút muối, tiêu rồi áp chảo sơ. Rót bột vào khuôn nóng có dầu, đặt tôm lên mặt, đậy nắp chiên đến khi viền giòn và bánh chín. Ăn cuốn rau sống, đồ chua và chấm nước mắm.'],
    ['Bánh ướt thịt nướng', 1, 'bánh ướt, thịt heo nạc vai, sả, tỏi, mật ong, nước mắm, dưa leo, rau thơm, hành phi, đồ chua', 'Ướp thịt nạc vai thái mỏng với sả, tỏi, mật ong và nước mắm rồi nướng hoặc áp chảo đến xém cạnh. Hấp bánh ướt cho mềm, rắc hành phi và rau thơm. Xếp thịt nướng, dưa leo và đồ chua lên bánh, cuộn hoặc gấp lại. Dùng với nước mắm chua ngọt.'],
    ['Bánh mì chảo pate trứng', 1, 'bánh mì, pate gan, trứng gà, xúc xích, thịt nguội, cà chua, hành tây, bơ, ngò rí', 'Phi thơm hành tây với bơ, thêm cà chua và nấu thành sốt sánh, nêm muối tiêu. Áp chảo xúc xích và thịt nguội, đặt pate vào chảo cho nóng. Đập trứng vào chảo, chiên đến độ chín mong muốn rồi rắc ngò rí. Dọn nóng cùng bánh mì giòn.'],
    ['Cơm gà Hội An', 1, 'gạo, thịt gà, nghệ, hành tây, gừng, tỏi, rau răm, dưa leo, nước mắm, chanh, ớt', 'Luộc gà với gừng và hành, giữ lại nước luộc. Xào gạo với tỏi và nghệ rồi nấu bằng nước luộc gà để cơm vàng thơm. Xé gà, trộn với hành tây thái mỏng, rau răm, chanh, nước mắm và tiêu. Xới cơm ra đĩa, đặt gà trộn lên trên, ăn kèm dưa leo và nước mắm ớt.'],
    ['Cơm chiên trái thơm hải sản', 1, 'cơm nguội, trái thơm, tôm, mực, trứng gà, cà rốt, đậu Hà Lan, hành lá, tỏi, nước mắm', 'Bổ trái thơm, lấy ruột và giữ vỏ làm thố. Xào tôm, mực với tỏi đến vừa chín rồi để riêng. Chiên trứng tơi, thêm cà rốt, đậu Hà Lan và cơm nguội, đảo lửa lớn cho hạt cơm săn. Cho hải sản và thơm vào, nêm nước mắm, tiêu, hành lá rồi xới vào vỏ thơm.'],

    // 14-26: Xào & mặn
    ['Gà xào sả ớt', 2, 'thịt gà, sả, ớt, hành tím, tỏi, nước mắm, đường, tiêu, lá chanh', 'Chặt gà miếng vừa ăn, ướp với nước mắm, tiêu và chút đường. Băm sả, hành tím, tỏi và ớt; phi thơm rồi cho gà vào xào săn trên lửa lớn. Thêm ít nước, rim đến khi gà chín và sốt áo đều. Rắc lá chanh thái sợi trước khi dùng.'],
    ['Bò xào bông cải xanh', 2, 'thịt bò, bông cải xanh, cà rốt, tỏi, dầu hào, nước tương, tiêu, dầu ăn', 'Thái bò mỏng, ướp nước tương, dầu hào và tiêu. Chần bông cải cùng cà rốt vừa chín tới, để ráo. Phi thơm tỏi, xào bò nhanh tay trên lửa lớn rồi trút ra. Xào rau củ, cho bò trở lại đảo đều và nêm vừa ăn.'],
    ['Mực xào sa tế', 2, 'mực ống, sa tế, hành tây, ớt chuông, cần tây, tỏi, nước mắm, đường, dầu ăn', 'Làm sạch mực, khứa vảy rồng và chần nhanh để mực săn. Phi tỏi với sa tế, cho mực vào xào lửa lớn, nêm nước mắm và chút đường. Thêm hành tây, ớt chuông và cần tây, đảo nhanh đến khi rau vừa chín nhưng còn giòn.'],
    ['Tôm rim nước dừa', 2, 'tôm sú, nước dừa tươi, hành tím, tỏi, nước mắm, đường, tiêu, hành lá', 'Rửa tôm, cắt râu và ướp với nước mắm, tiêu, hành tím. Phi thơm tỏi, cho tôm vào đảo đến đổi màu. Thêm nước dừa và đường, rim lửa vừa đến khi nước sốt sánh và bám quanh tôm. Rắc hành lá, dùng với cơm nóng.'],
    ['Cá thu sốt cà chua', 2, 'cá thu, cà chua, hành tím, tỏi, thì là, hành lá, nước mắm, đường, tiêu', 'Thấm khô cá thu, ướp muối tiêu rồi áp chảo vàng hai mặt. Phi hành tím và tỏi, cho cà chua thái nhỏ vào xào mềm, nêm nước mắm và đường. Thêm chút nước, đặt cá vào sốt và om đến khi cá thấm vị. Rắc thì là và hành lá.'],
    ['Sườn non ram mặn', 2, 'sườn non heo, hành tím, tỏi, nước mắm, đường, nước màu, tiêu, dầu ăn', 'Chặt sườn miếng vừa, chần sơ rồi ướp với nước mắm, đường, tiêu và nước màu. Phi hành tỏi, cho sườn vào áp chảo đến săn và xém cạnh. Thêm ít nước nóng, đậy nắp ram lửa nhỏ đến khi sườn mềm và nước cạn sệt.'],
    ['Ba chỉ rang cháy cạnh', 2, 'thịt ba chỉ, hành tím, nước mắm, đường, tiêu, hành lá, ớt, mè rang', 'Thái ba chỉ thành miếng mỏng vừa ăn, rang trên chảo nóng để mỡ tiết ra và cạnh thịt vàng xém. Gạn bớt mỡ, thêm hành tím và đảo thơm. Nêm nước mắm, đường, tiêu và ớt, đảo đến khi gia vị keo lại. Rắc hành lá và mè rang trước khi dùng.'],
    ['Đậu hũ sốt nấm đông cô', 2, 'đậu hũ non, nấm đông cô, nấm hương, hành boa-rô, tỏi, nước tương, dầu hào chay, bột năng, tiêu', 'Ngâm nấm đông cô, thái lát; cắt đậu hũ thành miếng và hấp nóng. Phi thơm hành boa-rô, xào nấm với tỏi rồi thêm nước tương, dầu hào chay và chút nước ngâm nấm. Làm sánh sốt bằng bột năng hòa nước, rưới lên đậu hũ và rắc tiêu.'],
    ['Trứng hấp thịt bằm', 2, 'trứng gà, thịt heo xay, hành tím, hành lá, nước mắm, tiêu, nước dùng', 'Trộn thịt heo xay với hành tím, nước mắm và tiêu, dàn vào đĩa chịu nhiệt. Đánh trứng với nước dùng, lọc qua rây rồi rót nhẹ lên thịt. Hấp lửa nhỏ, bọc nắp để mặt trứng mịn, đến khi trứng vừa đông và thịt chín. Rắc hành lá.'],
    ['Gà kho gừng', 2, 'thịt gà, gừng, hành tím, tỏi, nước mắm, nước màu, đường, tiêu, hành lá', 'Chặt gà, ướp với nước mắm, tiêu, nước màu và gừng thái sợi. Phi hành tím, tỏi rồi cho gà vào đảo săn. Thêm nước nóng và phần gừng còn lại, kho lửa nhỏ đến khi thịt chín mềm, nước kho sánh. Rắc hành lá trước khi dùng.'],
    ['Cá bống kho tiêu', 2, 'cá bống, tiêu sọ, hành tím, tỏi, nước mắm, nước màu, đường, ớt, hành lá', 'Làm sạch cá bống nhẹ tay để cá không nát, ướp với nước mắm, tiêu sọ, đường và nước màu. Xếp cá vào nồi cùng hành tím, tỏi và ớt, thêm ít nước nóng. Kho liu riu đến khi cá săn, thấm gia vị và nước kho cạn sệt. Rắc tiêu và hành lá.'],
    ['Heo quay kho cải chua', 2, 'thịt heo quay, cải chua, hành tím, tỏi, nước mắm, đường, nước dừa, tiêu', 'Rửa cải chua, vắt ráo và cắt khúc; thái heo quay miếng vừa. Phi hành tỏi, xào cải chua với chút đường rồi thêm heo quay. Nêm nước mắm, tiêu, thêm nước dừa và kho nhỏ lửa đến khi cải mềm, thịt thấm và nước kho sánh.'],
    ['Bò sốt tiêu đen', 2, 'thịt bò, tiêu đen, hành tây, ớt chuông, tỏi, dầu hào, nước tương, bột bắp', 'Thái bò thành lát dày, ướp dầu hào, nước tương, tiêu đen và bột bắp. Xào bò thật nhanh trên chảo nóng rồi gắp ra. Phi tỏi, xào hành tây và ớt chuông, thêm hỗn hợp sốt tiêu đen. Cho bò trở lại đảo vừa chín tới, dùng nóng.'],

    // 27-39: Sợi
    ['Bún riêu cua đồng', 3, 'bún tươi, cua đồng xay, cà chua, đậu hũ, trứng gà, hành tím, mắm tôm, giấm bỗng, rau muống bào', 'Lọc cua đồng lấy nước, đun lửa vừa để riêu nổi thành mảng rồi vớt riêng. Xào cà chua với hành tím, cho vào nồi nước cua cùng mắm tôm và giấm bỗng. Chiên đậu hũ, thả vào nồi; đánh trứng với riêu rồi hấp hoặc thả nhẹ để kết mảng. Chan nước dùng lên bún, ăn kèm rau sống.'],
    ['Bún mắm miền Tây', 3, 'bún tươi, mắm cá linh, mắm cá sặc, tôm, mực, cá basa, cà tím, sả, thịt heo quay, rau ăn kèm', 'Nấu mắm cá với nước, lọc bỏ xương. Phi sả và tỏi, đổ nước mắm đã lọc vào nồi, thêm nước dùng và cà tím, nêm vừa vị. Luộc hoặc chần tôm, mực, cá và thịt heo quay. Xếp bún cùng hải sản, chan nước lèo nóng, dùng với rau sống và chanh.'],
    ['Bún cá Châu Đốc', 3, 'bún tươi, cá lóc, nghệ, sả, mắm ruốc, nước dùng xương, rau muống bào, bắp chuối, giá, rau thơm', 'Luộc cá lóc với sả và nghệ, gỡ lấy thịt, giữ lại nước luộc. Nấu nước dùng với mắm ruốc đã lọc, sả đập dập và nghệ, nêm đậm đà. Xếp bún vào tô, đặt cá lên trên rồi chan nước lèo. Ăn cùng rau muống, bắp chuối, giá và rau thơm.'],
    ['Bún chả Hà Nội', 3, 'bún tươi, thịt ba chỉ, thịt heo xay, nước mắm, đường, tỏi, hành tím, đu đủ xanh, cà rốt, rau sống', 'Ướp ba chỉ thái lát và thịt xay viên với nước mắm, hành, tỏi, tiêu và đường; nướng than hoặc áp chảo đến xém thơm. Pha nước chấm chua ngọt, thêm đu đủ và cà rốt ngâm. Dọn bún, chả nướng, rau sống riêng, chan nước chấm nóng khi ăn.'],
    ['Bún ốc chuối đậu', 3, 'bún tươi, ốc nhồi, chuối xanh, đậu hũ, cà chua, mẻ, nghệ, tía tô, lá lốt, mắm tôm', 'Luộc ốc với gừng, lấy thịt và giữ nước luộc đã lọc. Chuối xanh tước vỏ, ngâm nước chanh rồi xào với nghệ; chiên đậu hũ. Nấu cà chua, nước ốc, mẻ và mắm tôm, cho chuối, đậu và ốc vào om đến thấm. Chan lên bún, rắc tía tô và lá lốt.'],
    ['Bún mọc sườn non', 3, 'bún tươi, sườn non, giò sống, nấm mèo, hành tím, nước dùng heo, hành lá, rau thơm', 'Ninh sườn non với hành tím đến mềm, hớt bọt để nước trong. Trộn giò sống với nấm mèo băm, tiêu và hành, vo viên rồi thả vào nồi nước dùng. Nêm nước mắm và muối, đun đến khi mọc nổi chín. Chan lên bún, rắc hành lá và rau thơm.'],
    ['Hủ tiếu Nam Vang', 3, 'hủ tiếu, tôm, thịt heo nạc, gan heo, trứng cút, xương heo, hành tím, hẹ, giá, cần tây', 'Ninh xương heo với hành tím để lấy nước dùng, nêm muối và nước mắm. Luộc tôm, thịt, gan và trứng cút; thái lát phần thịt và gan. Trụng hủ tiếu cùng giá, cho vào tô, xếp topping và chan nước dùng. Rắc hẹ, cần tây, hành phi và tiêu.'],
    ['Mì Quảng gà', 3, 'mì Quảng, thịt gà, nghệ, tôm, trứng cút, đậu phộng rang, bánh tráng mè, hành tím, rau sống', 'Ướp gà với nghệ, hành tím, nước mắm và tiêu rồi xào săn. Thêm tôm, nước dùng vừa đủ và trứng cút, rim thành phần nhân đậm vị. Trụng mì Quảng, xếp rau sống dưới tô, thêm mì và chan một lượng nước nhân vừa phải. Rắc đậu phộng, dùng với bánh tráng mè.'],
    ['Miến gà nấm hương', 3, 'miến dong, thịt gà, nấm hương, mộc nhĩ, hành tím, gừng, nước dùng gà, hành lá, rau mùi', 'Luộc gà với gừng và hành tím, vớt gà xé sợi và giữ nước luộc làm nước dùng. Ngâm nấm hương, mộc nhĩ rồi thái lát, xào thơm. Nấu nấm trong nước dùng, nêm nước mắm và tiêu. Trụng miến, cho vào tô cùng gà, chan nước dùng và rắc hành rau mùi.'],
    ['Miến lươn Nghệ An', 3, 'miến dong, lươn, nghệ, hành tăm, hành lá, rau răm, nước dùng xương, giá đỗ, ớt', 'Làm sạch lươn, luộc vừa chín rồi gỡ thịt; giữ lại nước luộc để nấu nước dùng. Xào lươn với hành tăm và nghệ đến thơm, nêm nước mắm, tiêu. Trụng miến và giá, xếp lươn lên trên rồi chan nước dùng nóng. Rắc hành lá, rau răm và ớt.'],
    ['Bánh đa cua Hải Phòng', 3, 'bánh đa đỏ, cua đồng, tôm, chả lá lốt, cà chua, rau muống, hành phi, mắm tôm, nước dùng xương', 'Lọc cua đồng và nấu lấy riêu; nêm mắm tôm vừa vị. Xào cà chua, cho vào nồi nước cua cùng nước dùng xương. Chiên chả lá lốt, chần rau muống và bánh đa đỏ. Xếp bánh, rau, tôm và chả vào tô rồi chan nước dùng, thêm hành phi.'],
    ['Bánh canh ghẹ', 3, 'bánh canh, ghẹ, xương heo, tôm khô, hành tím, dầu điều, bột năng, hành lá, ngò rí', 'Luộc ghẹ với sả, gỡ thịt và giữ phần mai để trang trí. Ninh xương với tôm khô và hành tím, lọc lấy nước dùng rồi nêm nước mắm, dầu điều. Cho bánh canh vào nấu chín, thêm thịt ghẹ. Hòa bột năng với nước để làm sánh nhẹ, múc ra tô và rắc hành ngò.'],
    ['Bánh canh cá lóc', 3, 'bánh canh, cá lóc, nghệ, sả, hành tím, nước dùng xương, hành lá, rau đắng, tiêu', 'Làm sạch cá lóc, luộc với sả và nghệ rồi gỡ lấy thịt; giữ nước luộc, lọc sạch xương. Ướp cá với nước mắm, tiêu rồi áp chảo sơ. Nấu nước dùng với sả, nghệ và nước luộc cá, thả bánh canh vào đến mềm. Cho cá lên tô, chan nước dùng và dùng cùng rau đắng.'],

    // 40-52: Canh & súp
    ['Canh bí đỏ nấu tôm khô', 4, 'bí đỏ, tôm khô, hành tím, nước dùng, hành lá, nước mắm, tiêu', 'Ngâm tôm khô cho mềm, rửa sạch rồi giã dập. Phi hành tím, xào tôm khô thơm rồi thêm nước dùng. Khi nước sôi, cho bí đỏ cắt miếng vào nấu đến mềm vừa. Nêm nước mắm, rắc hành lá và tiêu.'],
    ['Canh rau ngót thịt bằm', 4, 'rau ngót, thịt heo xay, hành tím, nước dùng, nước mắm, tiêu', 'Tuốt và vò nhẹ rau ngót, rửa sạch. Ướp thịt heo xay với nước mắm, tiêu và hành tím. Phi hành, xào thịt săn rồi đổ nước dùng vào đun sôi. Thả rau ngót, nấu vừa mềm, nêm lại rồi tắt bếp.'],
    ['Canh cua rau đay mồng tơi', 4, 'cua đồng xay, rau đay, mồng tơi, mướp hương, hành tím, mắm tôm, muối', 'Hòa cua xay với nước, bóp kỹ rồi lọc qua rây lấy nước cua. Đun nước cua lửa vừa, khuấy nhẹ đến khi riêu nổi thì vớt riêng. Cho mướp vào nấu mềm, tiếp đến thả rau đay và mồng tơi. Nêm muối, chút mắm tôm, cho riêu cua trở lại và tắt bếp.'],
    ['Canh măng vịt', 4, 'thịt vịt, măng tươi, gừng, hành tím, hành lá, rau răm, nước mắm, tiêu', 'Khử mùi vịt với gừng và muối, rửa sạch rồi chặt miếng. Luộc măng, xả nước và luộc lại nếu còn đắng. Xào vịt với hành tím đến săn, thêm nước nóng và nấu mềm. Cho măng vào nấu thấm, nêm nước mắm, tiêu, rắc hành lá và rau răm.'],
    ['Canh chua tôm bông súng', 4, 'tôm, bông súng, cà chua, me chua, thơm, giá đỗ, đậu bắp, rau om, ngò gai, nước mắm', 'Nấu nước với me, dầm lấy vị chua rồi lọc bỏ hạt. Thêm cà chua, thơm và đậu bắp, nấu sôi rồi cho tôm vào. Khi tôm vừa chuyển màu, thả bông súng và giá đỗ, nêm nước mắm và đường cho cân vị chua ngọt. Tắt bếp, thêm rau om và ngò gai.'],
    ['Canh bầu nấu nghêu', 4, 'bầu, nghêu, hành tím, gừng, hành lá, rau mùi, nước mắm, tiêu', 'Ngâm nghêu với nước muối loãng cho nhả cát, luộc đến khi mở miệng rồi lọc nước luộc. Tách thịt nghêu, xào nhanh với hành tím. Đun nước luộc nghêu cùng gừng, cho bầu thái lát vào nấu vừa trong. Thả nghêu vào, nêm nước mắm, rắc hành lá và tiêu.'],
    ['Canh cá nấu ngót', 4, 'cá lóc, cà chua, cần tây, hành lá, thì là, hành tím, nước dùng, nước mắm', 'Cắt cá thành khoanh, ướp với muối và tiêu. Phi hành tím, xào cà chua rồi thêm nước dùng, đun sôi. Thả cá vào nấu chín, hớt bọt và nêm nước mắm. Cho cần tây, hành lá và thì là vào sau cùng để giữ mùi thơm.'],
    ['Canh cải thảo cuộn thịt', 4, 'cải thảo, thịt heo xay, nấm mèo, miến, hành tím, nước dùng, hành lá, tiêu', 'Trụng lá cải thảo cho mềm. Trộn thịt xay với nấm mèo, miến cắt ngắn, hành tím và tiêu, đặt nhân lên lá rồi cuộn chặt. Xếp cuộn cải vào nồi nước dùng, nấu lửa nhỏ đến khi nhân chín và cải mềm. Nêm muối, rắc hành lá.'],
    ['Súp gà nấm hương', 4, 'thịt gà, nấm hương, bắp ngọt, trứng gà, nước dùng gà, bột năng, hành lá, tiêu', 'Luộc gà trong nước dùng, vớt ra xé sợi. Ngâm nấm hương, thái lát và nấu cùng bắp trong nước dùng. Cho gà trở lại nồi, nêm nước mắm và tiêu, làm sánh bằng bột năng hòa nước. Rót trứng đánh tan thành dòng mỏng, khuấy nhẹ rồi rắc hành lá.'],
    ['Súp bí đỏ kem tươi', 4, 'bí đỏ, hành tây, tỏi, nước dùng gà, kem tươi, bơ, tiêu, bánh mì nướng', 'Xào hành tây và tỏi với bơ đến mềm, thêm bí đỏ cắt khối và nước dùng. Nấu đến khi bí nhừ rồi xay mịn. Đun lại súp ở lửa nhỏ, khuấy kem tươi vào và nêm muối tiêu. Dùng nóng với bánh mì nướng.'],
    ['Súp hải sản trứng cút', 4, 'tôm, mực, thịt cua, trứng cút, bắp, nấm rơm, nước dùng, bột năng, trứng gà, ngò rí', 'Luộc trứng cút, bóc vỏ; sơ chế tôm, mực và nấm rơm. Nấu nước dùng với bắp và nấm, cho hải sản cùng thịt cua vào nấu vừa chín. Nêm gia vị, làm sánh bằng bột năng, thêm trứng cút. Rót trứng gà đánh tan vào nồi, khuấy tạo vân rồi rắc ngò rí.'],
    ['Súp lươn Nghệ An', 4, 'lươn, hành tăm, nghệ, ớt bột, nước dùng xương, hành lá, rau răm, bột năng, tiêu', 'Làm sạch lươn, luộc vừa chín rồi gỡ thịt, giữ lại nước luộc đã lọc. Phi hành tăm với nghệ và ớt bột, xào lươn cùng nước mắm, tiêu. Nấu nước dùng xương với nước luộc lươn, nêm vừa ăn và làm sánh nhẹ. Cho lươn vào bát, chan nước súp, rắc hành lá và rau răm.'],
    ['Canh nấm chua cay', 4, 'nấm kim châm, nấm đùi gà, nấm rơm, cà chua, đậu hũ non, sả, me chua, ớt, rau thơm', 'Phi sả, cho cà chua vào xào mềm rồi thêm nước và me chua đã lọc. Nêm nước tương, muối và ớt để có vị chua cay dịu. Cho nấm đùi gà, nấm rơm vào nấu trước, tiếp đến thêm nấm kim châm và đậu hũ non. Tắt bếp, rắc rau thơm.'],

    // 53-65: Hầm & lẩu
    ['Bò sốt vang', 5, 'bắp bò, cà chua, cà rốt, khoai tây, rượu vang đỏ, hành tây, tỏi, quế, hoa hồi, bánh mì', 'Ướp bò với tỏi, ngũ vị hương, muối tiêu và chút rượu vang. Áp chảo bò cho săn, thêm hành tây, cà chua, quế và hoa hồi, đảo thơm. Đổ nước nóng và vang đỏ, hầm đến khi bò mềm rồi cho cà rốt, khoai tây vào nấu chín. Nêm lại, dùng nóng với bánh mì.'],
    ['Vịt nấu chao', 5, 'thịt vịt, chao đỏ, khoai môn, nước dừa, sả, gừng, tỏi, hành tím, rau muống, bún tươi', 'Khử mùi vịt bằng gừng và rượu, chặt miếng rồi ướp chao, tỏi, hành tím và sả. Chiên sơ khoai môn cho vàng. Xào vịt săn, thêm nước dừa và nước nóng, hầm đến mềm rồi cho khoai môn vào. Nêm chao vừa vị, ăn nóng với bún và rau muống.'],
    ['Lẩu cá kèo lá giang', 5, 'cá kèo, lá giang, cà chua, thơm, sả, hành tím, rau nhút, rau muống, bún tươi, nước mắm', 'Rửa cá kèo với muối và chanh, để nguyên con. Nấu nước dùng với sả đập dập, cà chua và thơm; vò lá giang, cho vào nồi tạo vị chua. Nêm nước mắm, đường cho cân vị. Dọn cá và rau riêng, nhúng cá vào nồi sôi đến chín rồi ăn cùng bún.'],
    ['Lẩu gà lá é', 5, 'thịt gà, lá é, măng tươi, nấm bào ngư, sả, ớt xiêm xanh, hành tím, nước dùng gà, bún tươi', 'Chặt gà, ướp muối, tiêu và hành tím. Xào sả với ớt xiêm, cho gà vào đảo săn rồi thêm nước dùng và măng, hầm đến khi gà mềm. Nêm nước mắm và muối vừa ăn, thêm nấm bào ngư. Khi ăn nhúng lá é vào nồi sôi, dùng nóng với bún.'],
    ['Lẩu riêu cua bắp bò', 5, 'cua đồng xay, bắp bò, cà chua, đậu hũ, giấm bỗng, mắm tôm, hành tím, rau muống, hoa chuối, bún', 'Lọc cua, đun lấy riêu và giữ nước cua. Xào cà chua, nêm mắm tôm và giấm bỗng rồi hòa vào nồi nước dùng. Chiên đậu hũ, bày cùng bắp bò thái mỏng và rau. Khi ăn đun sôi lẩu, nhúng bò và rau vừa chín, ăn với bún.'],
    ['Lẩu Thái hải sản', 5, 'tôm, mực, nghêu, cá phi lê, sả, riềng, lá chanh, cà chua, nấm rơm, nước cốt me, ớt, rau ăn lẩu', 'Nấu sả, riềng và lá chanh trong nước dùng để lấy hương thơm. Thêm cà chua, nấm rơm, nước cốt me, ớt và gia vị lẩu Thái; nêm chua cay mặn ngọt. Bày tôm, mực, nghêu và cá cùng rau. Khi ăn nhúng hải sản và rau vào nồi sôi đến vừa chín.'],
    ['Lẩu mắm miền Tây', 5, 'mắm cá linh, mắm cá sặc, cá basa, tôm, mực, cà tím, sả, thịt ba chỉ, rau nhút, bông súng, bún', 'Nấu mắm cá với nước, lọc kỹ lấy nước cốt. Xào sả và thịt ba chỉ, thêm cà tím rồi đổ nước mắm đã lọc cùng nước dùng. Nêm đường và nước mắm cho dịu vị. Dọn cá, tôm, mực và các loại rau, nhúng lần lượt vào nồi lẩu sôi, ăn với bún.'],
    ['Gà tiềm thuốc bắc', 5, 'gà ác, táo đỏ, kỷ tử, hạt sen, hoài sơn, đẳng sâm, gừng, nấm hương, nước dùng', 'Rửa gà, chần sơ và để ráo. Ngâm hạt sen, nấm hương và các vị thuốc bắc; rửa sạch táo đỏ, kỷ tử. Cho gà cùng gừng, hạt sen, hoài sơn, đẳng sâm và nước dùng vào thố, tiềm lửa nhỏ đến mềm. Thêm táo đỏ, kỷ tử và nấm gần cuối, nêm nhẹ muối.'],
    ['Sườn non hầm củ sen', 5, 'sườn non, củ sen, cà rốt, táo đỏ, gừng, hành tím, nước dùng, hành lá', 'Chặt sườn, chần qua nước sôi rồi rửa sạch. Củ sen gọt vỏ, cắt khoanh và ngâm nước muối loãng. Ninh sườn với gừng, hành tím đến mềm, thêm củ sen, cà rốt và táo đỏ, hầm đến khi tất cả chín mềm. Nêm muối, rắc hành lá.'],
    ['Vịt om sấu', 5, 'thịt vịt, sấu xanh, khoai sọ, sả, gừng, hành tím, rau muống, nước mắm, rau ngổ', 'Khử mùi vịt bằng gừng và muối, chặt miếng rồi ướp nước mắm, tiêu. Xào vịt với sả và hành tím đến săn, thêm nước nóng cùng sấu, om nhỏ lửa. Khi vịt gần mềm, cho khoai sọ vào nấu chín. Dầm sấu điều chỉnh độ chua, rắc rau ngổ và dùng nóng.'],
    ['Lẩu nấm chay', 5, 'nấm đông cô, nấm đùi gà, nấm kim châm, nấm bào ngư, đậu hũ, bắp ngọt, củ cải trắng, táo đỏ, rau cải, mì', 'Nấu nước dùng chay từ củ cải, bắp và táo đỏ, lọc lấy nước trong. Nêm muối, nước tương và chút đường phèn. Xếp các loại nấm, đậu hũ và rau cải ra đĩa. Khi ăn đun sôi nước dùng, nhúng nấm và rau vừa chín, dùng với mì.'],
    ['Lẩu cá tầm măng chua', 5, 'cá tầm, măng chua, cà chua, thơm, sả, thì là, hành lá, nước dùng, bún tươi, rau ăn lẩu', 'Cá tầm làm sạch, cắt khoanh và ướp muối tiêu. Xào sả, cà chua và thơm, thêm nước dùng cùng măng chua, nấu sôi và nêm chua ngọt. Cho cá vào nấu đến chín, tránh khuấy mạnh làm nát. Rắc thì là, hành lá, ăn cùng bún và rau.'],
    ['Bò hầm tiêu xanh', 5, 'bắp bò, tiêu xanh, cà rốt, khoai tây, hành tây, tỏi, rượu vang, nước dùng bò, bánh mì', 'Cắt bắp bò khối, ướp muối tiêu và tỏi. Áp chảo bò, cho hành tây vào xào thơm rồi thêm rượu vang, nước dùng và nhánh tiêu xanh. Hầm đến khi bò gần mềm, thêm cà rốt, khoai tây và hầm tiếp. Nêm đậm đà, dùng với bánh mì.'],

    // 66-78: Chiên
    ['Gà chiên mắm tỏi', 6, 'cánh gà, nước mắm, tỏi, đường, tiêu, bột bắp, dầu ăn, rau thơm', 'Ướp cánh gà với tiêu và chút nước mắm, áo mỏng bột bắp. Chiên ngập dầu đến vàng giòn và chín bên trong. Phi tỏi, thêm nước mắm và đường nấu thành sốt sánh. Cho gà vào đảo nhanh cho áo đều sốt, rắc rau thơm.'],
    ['Cánh gà chiên bơ tỏi', 6, 'cánh gà, bơ lạt, tỏi, bột chiên giòn, nước mắm, tiêu, hành lá', 'Ướp cánh gà với muối tiêu, áo nhẹ bột chiên giòn. Chiên đến khi vàng giòn, vớt để ráo. Đun chảy bơ, phi tỏi đến thơm, nêm chút nước mắm. Cho gà vào đảo đều trong bơ tỏi, rắc hành lá.'],
    ['Mực chiên nước mắm', 6, 'mực ống, bột chiên giòn, nước mắm, tỏi, đường, ớt, hành lá, dầu ăn', 'Làm sạch mực, để thật ráo và cắt khoanh. Áo mực với bột chiên giòn rồi chiên nhanh trong dầu nóng đến vàng. Phi tỏi, thêm nước mắm, đường và ớt nấu sệt. Cho mực vào chảo đảo nhanh để sốt bám đều, rắc hành lá.'],
    ['Cá diêu hồng chiên giòn', 6, 'cá diêu hồng, muối, tiêu, bột bắp, dầu ăn, tỏi, nước mắm, chanh, rau sống', 'Làm sạch cá, khứa hai bên, thấm thật khô rồi xát muối tiêu và áo lớp bột bắp mỏng. Chiên ngập dầu, trở nhẹ đến khi da giòn và thịt chín. Pha nước mắm tỏi chanh ớt. Dọn cá nóng cùng rau sống và nước chấm.'],
    ['Cá lóc chiên xù sốt me', 6, 'cá lóc phi lê, bột chiên xù, trứng gà, bột mì, me chua, tỏi, đường, nước mắm, ớt', 'Cắt cá lóc miếng vừa, lăn qua bột mì, trứng đánh tan rồi bột chiên xù. Chiên đến vàng giòn, để ráo dầu. Nấu me với nước, lọc lấy cốt; phi tỏi, thêm nước me, nước mắm, đường và ớt, đun sánh. Rưới sốt me khi dùng.'],
    ['Đậu hũ non chiên giòn sốt trứng muối', 6, 'đậu hũ non, lòng đỏ trứng muối, bột bắp, bơ, sữa tươi, tỏi, hành lá, dầu ăn', 'Cắt đậu hũ thành miếng, thấm khô, lăn nhẹ bột bắp rồi chiên vàng giòn. Hấp chín lòng đỏ trứng muối và nghiền nhuyễn. Đun bơ, phi tỏi, cho trứng muối và chút sữa vào khuấy đến sủi bọt mịn. Áo đậu hũ bằng sốt, rắc hành lá.'],
    ['Khoai môn lệ phố', 6, 'khoai môn, đậu xanh cà vỏ, bột nếp, đường, mè trắng, bột chiên giòn, dầu ăn', 'Hấp khoai môn đến mềm, nghiền nhuyễn và nhào với bột nếp. Hấp đậu xanh, nghiền cùng đường thành nhân rồi vo viên. Bọc nhân bằng khoai môn, lăn mè và áo lớp bột chiên giòn. Chiên lửa vừa đến khi vỏ vàng giòn, để ráo dầu.'],
    ['Chả cá thác lác chiên thì là', 6, 'cá thác lác, thì là, hành lá, thìa là, nước mắm, tiêu, bột năng, dầu ăn', 'Quết cá thác lác với nước mắm, tiêu và bột năng đến dai. Trộn thì là và hành lá thái nhỏ, nặn thành miếng dẹt. Chiên lửa vừa đến khi chả vàng đều và chín bên trong. Dùng nóng với nước mắm chua ngọt.'],
    ['Bắp chiên bơ', 6, 'bắp ngọt, bột chiên giòn, bột năng, trứng gà, bơ lạt, muối, dầu ăn', 'Tách hạt bắp, trộn với trứng, bột chiên giòn, bột năng và chút muối để hạt vừa áo bột. Chiên từng mẻ nhỏ trong dầu nóng, đảo nhẹ đến khi hạt giòn vàng. Đun chảy bơ trong chảo, cho bắp chiên vào xóc đều. Dùng nóng.'],
    ['Cá hồi chiên sốt chanh dây', 6, 'phi lê cá hồi, chanh dây, bơ lạt, mật ong, kem tươi, muối, tiêu, dầu ô liu', 'Thấm khô cá hồi, nêm muối tiêu. Áp chảo mặt da trước với dầu ô liu đến giòn, trở mặt và chiên vừa chín. Lọc lấy nước chanh dây, đun cùng bơ, mật ong và kem tươi đến sánh nhẹ. Rưới sốt lên cá, dùng nóng.'],
    ['Ếch chiên nước mắm', 6, 'thịt ếch, bột chiên giòn, nước mắm, tỏi, đường, tiêu, hành lá, dầu ăn', 'Làm sạch ếch, chặt miếng và ướp tiêu, nước mắm. Áo ếch với bột chiên giòn, chiên đến chín vàng. Phi thơm tỏi, thêm nước mắm và đường nấu thành sốt. Cho ếch vào đảo nhanh cho thấm, rắc hành lá.'],
    ['Gà popcorn chiên giòn', 6, 'thịt ức gà, trứng gà, bột mì, bột bắp, bột chiên xù, tỏi bột, paprika, tiêu, dầu ăn', 'Cắt ức gà thành miếng nhỏ, ướp muối, tiêu, tỏi bột và paprika. Lăn từng miếng qua bột mì, trứng đánh tan rồi bột chiên xù. Chiên từng mẻ trong dầu nóng đến vàng giòn và chín hoàn toàn. Dùng cùng sốt mayonnaise hoặc tương ớt.'],
    ['Cá kèo chiên giòn', 6, 'cá kèo, bột chiên giòn, muối, tiêu, chanh, dầu ăn, rau sống, nước mắm', 'Rửa cá kèo với muối và chanh, để ráo rồi ướp nhẹ muối tiêu. Áo cá bằng bột chiên giòn, giũ bỏ phần bột thừa. Chiên ngập dầu đến khi cá vàng giòn, vớt lên giấy thấm dầu. Dùng nóng với rau sống và nước mắm tỏi ớt.'],

    // 79-91: Gỏi & rau
    ['Gỏi xoài xanh tôm khô', 7, 'xoài xanh, tôm khô, cà rốt, rau răm, đậu phộng rang, hành phi, nước mắm, đường, chanh, ớt', 'Ngâm tôm khô cho mềm rồi rang thơm. Bào xoài và cà rốt thành sợi, ngâm lạnh cho giòn rồi để ráo. Pha nước mắm với đường, chanh và ớt, trộn cùng xoài, cà rốt, tôm khô và rau răm. Rắc đậu phộng, hành phi trước khi ăn.'],
    ['Gỏi ngó sen tôm thịt', 7, 'ngó sen, tôm, thịt ba chỉ, cà rốt, rau răm, đậu phộng, hành phi, nước mắm, chanh, đường', 'Ngó sen cắt khúc, ngâm nước chanh loãng rồi vắt ráo. Luộc tôm và thịt ba chỉ, bóc vỏ tôm, thái thịt mỏng. Pha nước mắm chua ngọt, trộn với ngó sen, cà rốt, tôm thịt và rau răm. Rắc đậu phộng rang và hành phi.'],
    ['Gỏi bưởi tai heo', 7, 'bưởi, tai heo, tôm, rau răm, hành phi, đậu phộng rang, nước mắm, chanh, đường, ớt', 'Luộc tai heo với gừng đến chín, ngâm lạnh rồi thái lát mỏng. Luộc tôm, bóc vỏ; tách bưởi thành múi và bỏ hạt. Pha nước trộn gỏi từ nước mắm, chanh, đường và ớt. Trộn nhẹ bưởi, tai heo, tôm và rau răm, rắc hành phi, đậu phộng.'],
    ['Gỏi sứa hoa chuối', 7, 'sứa ăn liền, hoa chuối, cà rốt, rau thơm, đậu phộng, mè rang, nước mắm, chanh, đường, ớt', 'Rửa sứa nhiều lần, chần nhanh rồi để thật ráo. Bào hoa chuối, ngâm nước chanh cho trắng, vắt ráo; thái sợi cà rốt. Pha nước mắm chua ngọt, trộn với sứa, hoa chuối và rau thơm ngay trước khi ăn. Rắc đậu phộng, mè rang.'],
    ['Gỏi bò bóp thấu', 7, 'thịt bò, chuối chát, khế chua, hành tây, rau thơm, đậu phộng, hành phi, nước mắm, chanh, ớt', 'Thái bò mỏng, ướp tiêu và nước mắm rồi áp chảo nhanh cho vừa chín. Chuối chát và khế thái lát mỏng, ngâm nước chanh; hành tây thái sợi. Pha nước mắm chanh đường, trộn đều với bò, chuối, khế, hành tây và rau thơm. Rắc đậu phộng, hành phi.'],
    ['Gỏi gà bắp cải tím', 7, 'thịt gà, bắp cải tím, cà rốt, hành tây, rau răm, rau mùi, nước mắm, chanh, đường, đậu phộng', 'Luộc gà với gừng, để nguội rồi xé sợi. Thái bắp cải tím, cà rốt và hành tây thành sợi mỏng, ngâm lạnh rồi để ráo. Pha nước mắm chanh đường, trộn với gà, rau củ và rau răm. Để ngấm ngắn, rắc đậu phộng và rau mùi.'],
    ['Gỏi xoài cá khô', 7, 'xoài xanh, cá khô, rau răm, hành tím, đậu phộng rang, nước mắm, đường, chanh, ớt', 'Nướng hoặc áp chảo cá khô đến thơm, xé thành miếng nhỏ. Bào xoài xanh thành sợi, thái hành tím mỏng và ngâm lạnh. Pha nước mắm chua ngọt, trộn xoài với cá khô, rau răm và hành tím. Rắc đậu phộng, thêm ớt tùy khẩu vị.'],
    ['Nộm hoa chuối gà xé', 7, 'hoa chuối, thịt gà, cà rốt, rau thơm, đậu phộng, hành phi, nước mắm, chanh, đường', 'Luộc gà chín, để nguội rồi xé sợi. Thái hoa chuối thật mỏng, ngâm nước chanh muối để không thâm rồi vắt ráo. Trộn hoa chuối, cà rốt và gà với nước mắm chua ngọt, thêm rau thơm. Rắc đậu phộng rang và hành phi.'],
    ['Nộm rau muống tôm thịt', 7, 'rau muống, tôm, thịt ba chỉ, rau kinh giới, rau thơm, đậu phộng, nước mắm, chanh, đường, tỏi', 'Nhặt rau muống, chẻ sợi hoặc cắt khúc rồi chần nhanh, ngâm nước đá và để ráo. Luộc tôm và thịt ba chỉ, bóc vỏ tôm và thái thịt. Pha nước mắm tỏi chanh đường, trộn cùng rau muống, tôm thịt và rau thơm. Rắc đậu phộng khi dọn.'],
    ['Rau củ luộc chấm kho quẹt', 7, 'đậu bắp, cà rốt, bông cải xanh, cải thìa, thịt ba chỉ, tôm khô, nước mắm, đường, tiêu, hành lá', 'Ngâm tôm khô cho mềm, rang thơm cùng thịt ba chỉ thái hạt lựu. Thêm nước mắm, đường và tiêu, rim lửa nhỏ đến khi kho quẹt sánh, rắc hành lá. Cắt rau củ vừa ăn, luộc riêng từng loại trong nước sôi có chút muối để giữ màu. Dọn rau nóng cùng kho quẹt.'],
    ['Salad cá ngừ trứng', 7, 'cá ngừ, trứng gà, xà lách, cà chua bi, dưa leo, bắp hạt, hành tím, mayonnaise, mù tạt, chanh', 'Luộc trứng chín vừa, bóc vỏ và bổ múi. Rửa khô xà lách, cắt dưa leo và cà chua bi. Trộn mayonnaise với mù tạt, nước chanh và tiêu làm sốt. Xếp rau củ, cá ngừ và trứng ra đĩa, rưới sốt ngay trước khi dùng.'],
    ['Salad bơ tôm sú', 7, 'bơ chín, tôm sú, xà lách, cà chua bi, bắp hạt, hành tím, dầu ô liu, chanh, mật ong, tiêu', 'Luộc hoặc áp chảo tôm sú đến vừa chín, bóc vỏ và để nguội. Cắt bơ thành miếng, trộn nhẹ với nước chanh để không thâm. Pha dầu ô liu, chanh, mật ong, muối và tiêu thành sốt. Xếp xà lách, cà chua, bắp, bơ và tôm, rưới sốt khi ăn.'],
    ['Salad rau củ trộn sốt mè', 7, 'xà lách, bắp cải tím, cà rốt, dưa leo, cà chua bi, bắp hạt, mè rang, mayonnaise, mè trắng, nước tương, giấm gạo', 'Rửa sạch và để ráo xà lách; thái sợi bắp cải tím, cà rốt và dưa leo. Xay hoặc giã mè trắng, trộn với mayonnaise, nước tương, giấm gạo, chút đường và nước để tạo sốt mè sánh mịn. Trộn rau củ nhẹ tay với sốt, thêm cà chua bi và bắp hạt. Rắc mè rang rồi dùng ngay.'],

    // 92-104: Nước & chè
    ['Chè khúc bạch hạnh nhân', 8, 'sữa tươi, kem tươi, gelatin, đường, hạnh nhân lát, nhãn, vải, lá dứa', 'Ngâm gelatin cho nở. Đun sữa tươi, kem tươi và đường ở lửa nhỏ, khuấy tan rồi hòa gelatin vào, đổ khuôn và làm lạnh đến đông. Rang hạnh nhân lát vàng thơm. Cắt khúc bạch thành miếng, dùng với nước đường lá dứa, nhãn hoặc vải và rắc hạnh nhân.'],
    ['Chè đậu xanh nước cốt dừa', 8, 'đậu xanh cà vỏ, nước cốt dừa, đường, lá dứa, bột năng, muối, mè rang', 'Ngâm đậu xanh cho mềm, hấp hoặc nấu đến bở. Nấu đậu với lá dứa và đường, khuấy nhẹ để chè sánh nhưng còn hạt. Đun nước cốt dừa với chút muối, làm sánh bằng bột năng hòa nước. Múc chè ra bát, chan cốt dừa và rắc mè rang.'],
    ['Chè chuối chưng', 8, 'chuối sứ chín, nước cốt dừa, bột báng, đường, lá dứa, đậu phộng rang, muối', 'Ngâm bột báng cho mềm. Cắt chuối thành khoanh, ướp nhẹ với đường và muối. Nấu nước cốt dừa với lá dứa, cho bột báng vào nấu trong rồi thêm chuối, đun nhỏ lửa đến mềm và thơm. Múc chè ra bát, rắc đậu phộng rang.'],
    ['Chè bắp lá dứa', 8, 'bắp nếp, lá dứa, nước cốt dừa, đường, bột năng, muối, mè rang', 'Tách hạt bắp, giữ lõi để nấu cùng lá dứa lấy nước thơm rồi vớt bỏ lõi. Cho hạt bắp vào nấu đến mềm, thêm đường và chút muối. Hòa bột năng với nước, rót từ từ để chè sánh. Dùng nóng hoặc lạnh cùng nước cốt dừa và mè rang.'],
    ['Chè trôi nước gừng', 8, 'bột nếp, đậu xanh cà vỏ, gừng, đường thốt nốt, mè rang, nước cốt dừa, hành phi', 'Hấp đậu xanh chín mềm, nghiền với đường và hành phi làm nhân. Nhồi bột nếp với nước ấm, bọc nhân thành viên tròn. Luộc bánh đến khi nổi, vớt vào nồi nước đường thốt nốt nấu cùng gừng lát. Dùng nóng, chan nước cốt dừa và rắc mè rang.'],
    ['Chè sen long nhãn', 8, 'hạt sen tươi, nhãn, đường phèn, lá dứa, nước, muối', 'Bóc nhãn, bỏ hạt nhưng giữ cùi nguyên. Nấu hạt sen với nước đến mềm nhưng không nát, vớt sen và lọc nước. Nhồi hạt sen vào lòng nhãn, đun nước sen với đường phèn và lá dứa rồi để nguội. Cho nhãn bọc sen vào nước chè, dùng lạnh.'],
    ['Chè khoai dẻo', 8, 'khoai lang tím, khoai lang vàng, bột năng, đường, nước cốt dừa, lá dứa, gừng', 'Hấp riêng khoai tím và khoai vàng, nghiền nhuyễn khi còn nóng. Nhào từng loại với bột năng thành khối dẻo, lăn thành sợi và cắt viên nhỏ. Luộc viên khoai đến khi nổi, vớt vào nước lạnh. Nấu nước cốt dừa với lá dứa và đường, thêm khoai dẻo và ít gừng.'],
    ['Chè sương sa hạt lựu', 8, 'thạch rau câu, củ năng, bột năng, lá dứa, củ dền, nước cốt dừa, đường, đá bào', 'Nấu rau câu theo hướng dẫn, đổ khuôn và để đông rồi cắt sợi. Cắt củ năng hạt lựu, ngâm màu lá dứa hoặc củ dền, áo bột năng và luộc đến trong. Nấu nước đường lá dứa, để nguội; khuấy nước cốt dừa riêng. Cho thạch, hạt lựu, đá bào vào ly và chan nước đường, cốt dừa.'],
    ['Sâm bổ lượng', 8, 'bo bo, hạt sen, táo đỏ, nhãn nhục, phổ tai, củ sen, đường phèn, lá dứa', 'Ngâm riêng bo bo, phổ tai và hạt sen; rửa sạch táo đỏ, nhãn nhục. Nấu hạt sen và củ sen đến mềm, thêm bo bo nấu chín. Nấu nước đường phèn với lá dứa, cho táo đỏ và nhãn nhục vào nấu vừa mềm. Trộn các thành phần, thêm phổ tai đã chần, để lạnh trước khi dùng.'],
    ['Nước sấu ngâm', 8, 'quả sấu xanh, đường, gừng, muối, nước sôi để nguội', 'Cạo vỏ sấu, khía quanh quả rồi chần nhanh qua nước sôi có chút muối, để thật ráo. Xếp sấu vào hũ sạch, xen kẽ đường và gừng thái sợi. Đậy kín, để nơi thoáng đến khi đường tan và sấu tiết nước. Khi uống pha nước sấu ngâm với nước lọc, thêm đá tùy thích.'],
    ['Rau má đậu xanh', 8, 'rau má, đậu xanh cà vỏ, nước lọc, đường, sữa đặc, đá viên', 'Ngâm đậu xanh, hấp chín mềm rồi để nguội. Rửa rau má nhiều lần, xay với nước lọc rồi lọc lấy nước cốt. Xay lại nước rau má với đậu xanh, đường và sữa đặc đến mịn. Rót ra ly, thêm đá và khuấy đều.'],
    ['Trà tắc xí muội', 8, 'trà đen, tắc, xí muội, đường, mật ong, nước nóng, đá viên', 'Ủ trà đen với nước nóng đến khi có màu và hương đậm, lọc bỏ bã rồi để nguội. Dầm xí muội với đường và mật ong, thêm nước cốt tắc. Rót trà vào bình lắc cùng hỗn hợp xí muội và đá, lắc đều. Rót ra ly, thêm lát tắc.'],
    ['Nước mía sầu riêng', 8, 'mía cây, múi sầu riêng chín, đá viên, tắc', 'Ép mía lấy nước, lọc bỏ bã và làm lạnh. Tách múi sầu riêng, bỏ hạt rồi dằm hoặc xay mịn với một ít nước mía. Khuấy phần sầu riêng vào nước mía đến hòa quyện, điều chỉnh độ sánh theo khẩu vị. Thêm đá và vài giọt tắc trước khi uống.'],
];
